INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46711, 'Judges 9:12', 'Judges', 9, 12, 'بیا ونو د انګورو تاک ته وویل: راځه زمونږ پاچا شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_12.mp3', '', 1761754199, 1761754199),
(46712, 'Judges 9:13', 'Judges', 9, 13, 'خو تاک هم په ځواب کې وویل: ایا زه په تاسو باندې د پاچاهي کولو په خاطر د خپلو شرابو د تولیدولو څخه چې خدایان او انسانان خوشحالوي، لاس واخلم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_13.mp3', '', 1761754199, 1761754199),
(46713, 'Judges 9:14', 'Judges', 9, 14, 'په پای کې ټولو ونو د اغزیو بوټي ته وویل: ‹راځه ته زمونږ پاچا شه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_14.mp3', '', 1761754199, 1761754199),
(46714, 'Judges 9:15', 'Judges', 9, 15, 'د اغزیو بوټي په ځواب کې وویل: ‹که چېرې تاسو په رښتیا غواړئ چې زه ستاسو پاچا شم، نو بیا راشئ او زما د سیوري لاندې پناه واخلئ. که نه، نو زما د اغزینو څانګو څخه به د اور لمبه پورته شي او حتی د لبنان د سبر ونې به هم وسوځوي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_15.mp3', '', 1761754199, 1761754199),
(46715, 'Judges 9:19', 'Judges', 9, 19, 'نو که چېرې هغه کار چې تاسو نن د جدعون او د هغه د کورنۍ سره وکړ، د اخلاص او صداقت له مخې وي، نو بیا تاسو دې د ابیملک څخه خوشحاله اوسئ او هغه دې ستاسو څخه خوشحاله اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_19.mp3', '', 1761754199, 1761754199),
(46716, 'Judges 9:20', 'Judges', 9, 20, 'که نه، نو د ابیملک څخه دې د اور لمبه راووځي او د شکیم او بیت ملو سړي دې وسوځوي. او د شکیم او بیت ملو د سړیو څخه دې د اور لمبه راووځي او ابیملک دې وسوځوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_20.mp3', '', 1761754199, 1761754199),
(46717, 'Judges 9:21', 'Judges', 9, 21, 'بیا یوتام وتښتېده او لاړ چې په بییر کې واوسیږي، ځکه چې هغه د خپل ورور ابیملک څخه وېرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_21.mp3', '', 1761754199, 1761754199),
(46718, 'Judges 9:22', 'Judges', 9, 22, 'ابیملک په اسراییلو باندې درې کاله حکومت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_22.mp3', '', 1761754199, 1761754199),
(46719, 'Judges 9:23', 'Judges', 9, 23, 'بیا خدای د ابیملک او د شکیم د خلکو ترمنځ دښمني پیدا کړه او هغوی د ابیملک په وړاندې خیانت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_23.mp3', '', 1761754199, 1761754199),
(46720, 'Judges 9:24', 'Judges', 9, 24, 'دا کار د دې دپاره وشو، ترڅو ابیملک او د شکیم خلک چې د هغه سره یې د جدعون د اویا زامنو په قتلولو کې مرسته کړې وه، د خپلو عملونو سزا وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_24.mp3', '', 1761754199, 1761754199),
(46721, 'Judges 9:25', 'Judges', 9, 25, 'د ابیملک په خلاف د شکیم خلکو په غونډیو باندې کسان په کمین کې کښېنول او هرڅوک چې به د هغه ځای نه تېرېده هغه به یې لوټاوه او ابیملک د دې کار څخه خبر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_25.mp3', '', 1761754199, 1761754199),
(46722, 'Judges 9:26', 'Judges', 9, 26, 'په دې وخت کې جعل د عابد زوی د خپلو ورونو سره شکیم ته کډه وکړه او د هغه ځای اوسېدونکو په هغه باندې اعتبار وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_26.mp3', '', 1761754199, 1761754199),
(46723, 'Judges 9:27', 'Judges', 9, 27, 'د انګورو د حاصلاتو وخت راورسېده او د شکیم خلک خپلو باغونو ته ورننوتل او انګور یې راټول کړل. د هغو څخه یې شراب جوړ کړل او جشن یې ونیوه. بیا هغوی د خپل خدای عبادتځای ته لاړل، هلته یې خوراک وکړ او شراب یې وڅښل او په ابیملک باندې یې ملنډې ووهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_27.mp3', '', 1761754199, 1761754199),
(46724, 'Judges 9:28', 'Judges', 9, 28, 'جعل وویل: «مونږ د شکیم خلک څه ډول خلک یو؟ ولې مونږ د ابیملک خدمت کوو؟ هغه څوک دی؟ ایا هغه د جدعون زوی او زبول د هغه مرستیال نه دی؟ خو مونږ ولې د هغه خدمت وکړو؟ خپل نیکه حمور ته چې ستاسو د طایفې بنیاد یې کېښود، وفادار اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_28.mp3', '', 1761754199, 1761754199),
(46725, 'Judges 9:29', 'Judges', 9, 29, 'کاشکې زه ستاسو مشر وای، نو تاسو به مې د ابیملک د شر څخه خلاص کړي وای. ما به هغه ته ویلي وای چې خپل ټول لښکر دې راوغواړه او جنګ ته راووځه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_29.mp3', '', 1761754199, 1761754199),
(46726, 'Judges 9:30', 'Judges', 9, 30, 'کله چې د ښار والي زبول د جعل دا خبره واورېدله، هغه ډېر په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_30.mp3', '', 1761754199, 1761754199),
(46727, 'Judges 9:31', 'Judges', 9, 31, 'هغه په پټه ابیملک ته استازي ولېږل او استازو ورته وویل: «د عابد زوی جعل د خپلو ورونو سره شکیم ته راغلی دی او هغوی ستا په خلاف د ښار اوسېدونکي راپاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_31.mp3', '', 1761754199, 1761754199),
(46728, 'Judges 9:32', 'Judges', 9, 32, 'ته باید د خپلو کسانو سره د شپې راشې او په پټیو کې پټ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_32.mp3', '', 1761754199, 1761754199),
(46729, 'Judges 9:33', 'Judges', 9, 33, 'سبا سهار د لمرخاته په وخت کې پاڅه او په ښار باندې یوه ناڅاپه حمله وکړه. کله چې جعل د خپلو کسانو سره ستا په وړاندې جګړې ته راووځي، نو ته د هغوی سره په خپل ټول قوت مقابله وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_33.mp3', '', 1761754199, 1761754199),
(46730, 'Judges 9:34', 'Judges', 9, 34, 'نو د شپې له خوا ابیملک او د هغه لښکرې روانې شوې، هغوی په څلورو ډلو کې سره ووېشل شول او د شکیم څخه دباندې پټ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_34.mp3', '', 1761754199, 1761754199),
(46731, 'Judges 9:35', 'Judges', 9, 35, 'کله چې ابیملک او د هغه کسانو ولیدل چې جعل راوتلی او د ښار د دروازې په خولې کې ولاړ دی، نو هغوی د خپلو پټو ځایونو څخه راووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_35.mp3', '', 1761754199, 1761754199),
(46732, 'Judges 9:36', 'Judges', 9, 36, 'جعل هغوی ولیدل او زبول ته یې وویل: «ګوره، د غرونو د څوکو څخه خلک راښکته کیږي.» زبول په ځواب کې وویل: «هغه سړي نه دي، هغه یوازې د غرونو سیوري دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_36.mp3', '', 1761754199, 1761754199),
(46733, 'Judges 9:37', 'Judges', 9, 37, 'جعل بیا وویل: «ګوره! خلک د غره څخه راښکته کیږي او بله ډله یې د څېړۍ د ونې په لاره په هغه ځای کې چې خلک فال ګوري، راروانه ده!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_37.mp3', '', 1761754199, 1761754199),
(46734, 'Judges 9:38', 'Judges', 9, 38, 'بیا زبول هغه ته وویل: «اوس ستا لافې چېرته دي؟ تا به پوښتنه کوله چې ولې باید د ابیملک خدمت وکړو. دا هغه کسان دي چې تا ورباندې ملنډې وهلې. اوس لاړ شه او جګړه ورسره وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_38.mp3', '', 1761754199, 1761754199),
(46735, 'Judges 9:39', 'Judges', 9, 39, 'جعل د شکیم کسان راوویستل او د ابیملک سره یې جګړه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_39.mp3', '', 1761754199, 1761754199),
(46736, 'Judges 9:40', 'Judges', 9, 40, 'جعل وتښتېد او ابیملک ورپسې شو. د ښار د دروازې تر خولې پورې ډېر کسان ټپیان پراته وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_40.mp3', '', 1761754199, 1761754199),
(46737, 'Judges 9:41', 'Judges', 9, 41, 'ابیملک په ارومه کې سکونت اختیار کړ. زبول، جعل او د هغه ورونه د شکیم څخه وویستل، نو هغوی ونه شو کولای چې نور هلته واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_41.mp3', '', 1761754199, 1761754199),
(46738, 'Judges 9:42', 'Judges', 9, 42, 'بله ورځ ابیملک خبر شو چې د شکیم خلک غواړي چې پټیو ته ووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_42.mp3', '', 1761754199, 1761754199),
(46739, 'Judges 9:43', 'Judges', 9, 43, 'نو هغه خپل کسان په درېو ډلو ووېشل او هغوی په پټیو کې پټ شول او انتظار یې کاوه. کله چې هغه ولیدل چې خلک د ښار څخه راوځي، نو هغوی د پټېدلو د ځای څخه راووتل او د شکیم په خلکو باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_43.mp3', '', 1761754199, 1761754199),
(46740, 'Judges 9:44', 'Judges', 9, 44, 'ابیملک د خپلو کسانو سره په بیړه مخکې لاړ چې د ښار دروازه ونیسي، په دې وخت کې نورو دوو ډلو په هغو خلکو باندې چې په پټیو کې وو، حمله وکړه او ټول یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_44.mp3', '', 1761754199, 1761754199),
(46741, 'Judges 9:45', 'Judges', 9, 45, 'جنګ ټوله ورځ دوام وموند. هغوی ښار ونیوه او د هغه ځای خلک یې ووژل. ښار یې وران کړ او په ځمکه باندې یې مالګه وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_45.mp3', '', 1761754199, 1761754199),
(46742, 'Judges 9:46', 'Judges', 9, 46, 'د دې خبرې په اورېدلو سره کوم ښاریان چې د شکیم په برج کې وو، د بعل بریت د بتخانې کلا ته ننوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_46.mp3', '', 1761754199, 1761754199),
(46743, 'Judges 9:47', 'Judges', 9, 47, 'کله چې ابیملک خبر شو چې هغوی هلته راټول شوي دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_47.mp3', '', 1761754199, 1761754199),
(46744, 'Judges 9:48', 'Judges', 9, 48, 'نو د خپلو ټولو کسانو سره د صلمون غره ته وخوت. هغه تبر واخیست او یو څو څانګې یې پرې کړې او په خپلو اوږو باندې یې کېښودلې. هغه په خپلو کسانو باندې حکم وکړ: «زر شئ! کوم کار چې زه یې کوم، تاسو یې هم وکړئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_48.mp3', '', 1761754199, 1761754199),
(46745, 'Judges 9:49', 'Judges', 9, 49, 'نو هر سړي د ونې څخه یوه یوه څانګه پرې کړه، بیا هغوی ابیملک پسې روان شول او هغه لرګي یې د کلا په دېوالونو باندې کېښودل او هغه کلا یې وسوځوله. نو د شکیم د کلا ټول خلک چې شاوخوا زر تنه نارینه او ښځې وې، مړه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_49.mp3', '', 1761754199, 1761754199),
(46746, 'Judges 9:50', 'Judges', 9, 50, 'بیا ابیملک د تاباز په ښار باندې حمله وکړه. ښار یې کلابند کړ او هغه یې ونیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_50.mp3', '', 1761754199, 1761754199),
(46747, 'Judges 9:51', 'Judges', 9, 51, 'دننه په ښار کې یو قوي برج ؤ چې د ښار ټول سړي او ښځې د مشرانو سره هغه ته وروتښتېدل. د خپلو ځانونو پسې یې دروازې وتړلې او بام ته وختل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_51.mp3', '', 1761754199, 1761754199),
(46748, 'Judges 9:52', 'Judges', 9, 52, 'کله چې ابیملک راغی چې په برج باندې حمله وکړي، نو دروازو ته ورغی چې برج ته اور واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_52.mp3', '', 1761754199, 1761754199),
(46749, 'Judges 9:53', 'Judges', 9, 53, 'خو یوې ښځې د بام د سر څخه د هغه په سر باندې د مېچنې پل راوغورځاوه او د هغه کوپړۍ یې ماته کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_53.mp3', '', 1761754199, 1761754199),
(46750, 'Judges 9:54', 'Judges', 9, 54, 'ابیملک زر خپل عسکرو ته چې وسلې یې ورسره وړلې، غږ وکړ: «خپله توره راوباسه او ما ووژنه. زه نه غواړم چې خلک ووایي چې ابیملک د یوې ښځې د لاسه ووژل شو.» نو هغه ځوان د هغه په ګېډه کې توره ورومنډله او هغه مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_54.mp3', '', 1761754199, 1761754199),
(46751, 'Judges 9:55', 'Judges', 9, 55, 'کله چې اسراییلیانو ولیدل چې ابیملک مړ دی، نو ټول خپلو کورونو ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_55.mp3', '', 1761754199, 1761754199),
(46752, 'Judges 9:56', 'Judges', 9, 56, 'په دې ډول خدای د ابیملک څخه د هغه جرم بدله واخیستله چې هغه د خپل پلار په وړاندې کړی ؤ او خپل اویا ورونه یې وژلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_56.mp3', '', 1761754199, 1761754199),
(46753, 'Judges 9:57', 'Judges', 9, 57, 'همدارنګه خدای د شکیم د خلکو څخه د هغوی د ټولو بدو کارونو بدله واخیستله او د جدعون د زوی یوتام لعنت په هغوی باندې راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_57.mp3', '', 1761754199, 1761754199),
(46754, 'Psalms 16:1', 'Psalms', 16, 1, 'ته مې وساته ای خدایه، زه پناه غواړم له تا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_1.mp3', '', 1761754199, 1761754199),
(46755, 'Psalms 16:2', 'Psalms', 16, 2, 'ما دا وویل څښتن ته: «ته زما څښتن یې ټول زما نعمتونه دي د ستا له خوا نه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_2.mp3', '', 1761754199, 1761754199),
(46756, 'Psalms 16:3', 'Psalms', 16, 3, 'د وطن سپېڅلي خلک، شریف خلک دي! په هغوی کې زما ټوله خوشحالي ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_3.mp3', '', 1761754199, 1761754199),
(46757, 'Psalms 16:4', 'Psalms', 16, 4, 'چې ځغلي څوک نورو خدایانو پسې د هغو خلکو به غمونه زیات شي د هغو خلکو قربانیو کې به نه شم شریک نه به یې نومونه د خدایانو واخلم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_4.mp3', '', 1761754199, 1761754199),
(46758, 'Psalms 16:5', 'Psalms', 16, 5, 'ته زما دپاره هرڅه یې څښتنه زه چې هر شي ته محتاج شم هغه ته راکوې ماته زما قسمت ستا په لاسونو کې دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_5.mp3', '', 1761754199, 1761754199),
(46759, 'Psalms 16:6', 'Psalms', 16, 6, 'تا ماته په برخه کې راکړي ښه ځایونه دي هېڅ په کې شک نشته چې ښایسته زما میراث دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_6.mp3', '', 1761754199, 1761754199),
(46760, 'Psalms 16:7', 'Psalms', 16, 7, 'کوم ستاینه د څښتن چې کوي ماته لارښوونه حتی په شپه کې مې وجدان راته کوي سمه ښودنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_7.mp3', '', 1761754199, 1761754199),
(46761, 'Psalms 16:8', 'Psalms', 16, 8, 'څښتن تل زما سره دی زه پوهېږم هغه موجود دی زما ښي لاس ته نو زه به نه غورځېږم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_8.mp3', '', 1761754199, 1761754199),
(46762, 'Psalms 16:9', 'Psalms', 16, 9, 'نو زما زړه دی خوشحال او خوشحالي کومه هم بدن مې دی په امن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_9.mp3', '', 1761754199, 1761754199),
(46763, 'Psalms 16:10', 'Psalms', 16, 10, 'ځکه چې ته به ما پرېنږدې د مړو په دنیا کې او ته به پرېنږدې مړی د خپل سپېڅلي خادم چې شي خراب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_10.mp3', '', 1761754199, 1761754199),
(46764, 'Psalms 16:11', 'Psalms', 16, 11, 'راښایې ماته د ژوندون لاره ډک دی زما زړه د خوشحالۍ نه ستا دیدار سره ستا ښي لاس ته ناست به تل خوشحاله یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms16_verse_11.mp3', '', 1761754199, 1761754199),
(46765, 'Jeremiah 2:1', 'Jeremiah', 2, 1, 'د مالِک خُدائ کلام په ما نازل شو او راته يې وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_1.mp3', '', 1761754199, 1761754199),
(46766, 'Jeremiah 2:2', 'Jeremiah', 2, 2, '”لاړ شه او د يروشلم خلقو ته دا پېغام ورسوه. ما ته ستاسو د ځوانۍ وفادارى ښۀ ياده ده، چې تاسو به څنګه لکه د ناوې په شان ما سره مينه کوله او تر دې چې په صحرا کښې چې په کښې کله هم څۀ نۀ کېدل بيا هم تاسو ما پسې راروان وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_2.mp3', '', 1761754199, 1761754199),
(46767, 'Jeremiah 2:3', 'Jeremiah', 2, 3, 'په هغه ورځو کښې بنى اِسرائيل مالِک خُدائ ته مقدس خلق وُو او د هغۀ د فصل وړومبۍ مېوه وه. او چا به چې هغوئ ته نقصان رسولو نو هغوئ به ما مجرمان ګرځول او په هغوئ به مې مصيبتونه نازلول، ما مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_3.mp3', '', 1761754199, 1761754199),
(46768, 'Jeremiah 2:4', 'Jeremiah', 2, 4, 'اے د يعقوب اولاده، اے د بنى اِسرائيلو ټولو قبيلو، د مالِک خُدائ کلام ته غوږ ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_4.mp3', '', 1761754199, 1761754199),
(46769, 'Jeremiah 2:5', 'Jeremiah', 2, 5, 'مالِک خُدائ فرمائى، ”ستاسو پلار نيکۀ په ما کښې څۀ غلطى ليدلې وه چې هغوئ زما نه دومره لرې شول؟ هغوئ د بې‌کاره بُتانو عبادت شروع کړو او په خپله هم بې‌کاره شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_5.mp3', '', 1761754199, 1761754199),
(46770, 'Jeremiah 2:6', 'Jeremiah', 2, 6, 'هغوئ دا تپوس قدرې هم ونۀ کړو چې، ”مالِک خُدائ چرته دے، چا چې مونږ د مِصر نه رابهر کړو، او په هغه صحرا کښې يې زمونږ لارښودنه وکړه چې د ميرو او کندو کپرو مُلک وو، هر طرف ته خُشکه او تيارۀ وه چې په کومه زمکه کښې نۀ چا سفر کولو او نۀ په کښې څوک اوسېدل؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_6.mp3', '', 1761754199, 1761754199),
(46771, 'Jeremiah 2:7', 'Jeremiah', 2, 7, 'ما تاسو د باغونو نه ډک او زرخيزه مُلک ته راوستلئ چې د دې د مېوو او د نورو ښو څيزونو نه خوند واخلئ. خو کله چې تاسو په هغه مُلک کښې ورداخل شوئ نو هغه تاسو په ګناه سره پليت کړو او په دې وجه مو زما ميراثى مُلک قابل نفرت وګرځولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_7.mp3', '', 1761754199, 1761754199),
(46772, 'Jeremiah 2:8', 'Jeremiah', 2, 8, 'اِمامانو هم دا تپوس ونۀ کړو چې، ”مالِک خُدائ چرته دے؟“ او تر دې چې د شريعت خادِمانو هم زۀ ونۀ پېژندم، د قوم مشرانو زما خلاف سرکشى وکړه، او د هغوئ نبيانو د بعل د بُت پېغام اورولو او د بې‌کاره بُتانو پيروى او عبادت يې کولو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_8.mp3', '', 1761754199, 1761754199),
(46773, 'Jeremiah 2:9', 'Jeremiah', 2, 9, 'مالِک خُدائ فرمائى چې، ”نو په دې وجه به زۀ د خپلو خلقو خلاف اِلزام ولګوم. او زۀ به ستاسو په اولاد هم نسل در نسل اِلزام ولګوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_9.mp3', '', 1761754199, 1761754199),
(46774, 'Jeremiah 2:10', 'Jeremiah', 2, 10, 'مغرب طرف ته د سمندر په بله خوا کښې د قبرص جزيرې ته لاړ شه او وګوره، او د مشرق طرف ته د قيدار مُلک ته څوک ولېږه چې په غور سره لټون وکړى چې آيا د دې نه وړاندې هم داسې کار شوے دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_10.mp3', '', 1761754199, 1761754199),
(46775, 'Jeremiah 2:11', 'Jeremiah', 2, 11, 'تاسو چرې يو قوم داسې هم ليدلے دے چې د خپلو خُدايانو نه اوړېدلى وى کوم چې په حقيقت کښې خُدائ پاک هم نۀ دے؟ نه، بلکل نه. خو زما غوره شوے قوم زۀ خپل جلالى مالِک خُدائ پرېښودم او زما په ځائ يې د بې‌فائدې بُتانو عبادت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_11.mp3', '', 1761754199, 1761754199),
(46776, 'Jeremiah 2:12', 'Jeremiah', 2, 12, 'اے آسمانونو تاسو خوف زده شئ او پرېشانه شئ،“ مالِک خُدائ فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_12.mp3', '', 1761754199, 1761754199),
(46777, 'Jeremiah 2:13', 'Jeremiah', 2, 13, '”ځکه چې زما خلقو دوه ګناهونه کړى دى، يو دا چې هغوئ زۀ چې د ژوندون د اوبو چينه يم پرېښودے يم، او بل دا چې د خپل ځان دپاره يې مات شوى تالابونه جوړ کړى دى په کوم کښې چې اوبۀ نۀ ايساريږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_13.mp3', '', 1761754199, 1761754199),
(46778, 'Jeremiah 2:14', 'Jeremiah', 2, 14, '”ولې بنى اِسرائيليان غلامان دى څۀ؟ ولې هغوئ غلامان پېدا شوى دى څۀ؟ نو بيا ولې هغوئ اغوا کړے شول؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_14.mp3', '', 1761754199, 1761754199),
(46779, 'Jeremiah 2:15', 'Jeremiah', 2, 15, 'هغوئ د غړمبېدونکو زمرو په شان په دوئ باندې حمله وکړه، او د دوئ د زمکې نه يې صحرا جوړه کړه، او ښارونه يې ورته وسوزول او د اوسېدو نه يې وويستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_15.mp3', '', 1761754199, 1761754199),
(46780, 'Jeremiah 2:16', 'Jeremiah', 2, 16, 'د دې نه علاوه، د ميمفِس او د تحفنحيس خلق راغلل او ستاسو سرونه يې وخرائېل او غلامان يې جوړ کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_16.mp3', '', 1761754199, 1761754199),
(46781, 'Jeremiah 2:17', 'Jeremiah', 2, 17, 'اے بنى اِسرائيلو، ولې دا تاسو په خپله په خپل ځان نۀ دى کړى څۀ؟ کله چې مالِک ستاسو خُدائ پاک ستاسو رهنمائى کوله نو بيا په هغه وخت کښې تاسو هغه پرېښودو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_17.mp3', '', 1761754199, 1761754199),
(46782, 'Jeremiah 2:18', 'Jeremiah', 2, 18, 'نو بيا مِصر ته د تلو او د دريائے نيل د اوبو څښلو څۀ فائده ده؟ او بيا اسور ته د تلو او د فرات د سيند د اوبو څښلو څۀ فائده ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_18.mp3', '', 1761754199, 1761754199),
(46783, 'Jeremiah 2:19', 'Jeremiah', 2, 19, 'ستاسو شرارت به تاسو له سزا درکړى، او زما نه ستاسو د اوړېدو په وجه به تاسو ورټلے شئ. نو بيا تاسو په دې غور وکړئ او ځان خبر کړئ چې دا به ستاسو دپاره څومره بده او ترخه وى کله چې تاسو مالِک خُدائ ستاسو خُدائ پاک پرېږدئ او تاسو د هغۀ نه، نۀ يرېږئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_19.mp3', '', 1761754199, 1761754199),
(46784, 'Jeremiah 2:20', 'Jeremiah', 2, 20, '”اے بنى اِسرائيلو، تاسو د ډېر پخوا نه زما جغ د خپل څټ نه اخوا کړے دے او زما نه مو اِنکار کړے دے. تاسو ووئيل، ”زۀ به نور ستا بندګى نۀ کوم.“ په هره لوړه غونډۍ او د هرې شنې ونې لاندې څملاستئ او د کنجرو په شان مو زنا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_20.mp3', '', 1761754199, 1761754199),
(46785, 'Jeremiah 2:21', 'Jeremiah', 2, 21, 'ما تاسو د نورو انګورو د ښو بوټو د مينځ نه غوره کړئ او په زمکه مې وکرلئ خو بيا تاسو ولې فاسد او په خراب او ځنګلى انګورو بوټى بدل شوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_21.mp3', '', 1761754199, 1761754199),
(46786, 'Jeremiah 2:22', 'Jeremiah', 2, 22, 'کۀ څۀ هم تاسو خپل ځان په سوډا او ډېر صابون باندې ووينځئ، خو بيا هم ستاسو د ګناه داغونه زما په وړاندې دى.“ دا د قادر مطلق خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_22.mp3', '', 1761754199, 1761754199),
(46787, 'Jeremiah 2:23', 'Jeremiah', 2, 23, '”تۀ څنګه وائې چې ما خپل ځان نۀ دے ګنده کړے او د بعل د بُت پيروى مې نۀ ده کړى؟ ګوره تا په هغه دره کښې څنګه رفتار وکړو. لږ ځان سره سوچ وکړه چې تا هلته څۀ کړى دى. تۀ هغه اوښه يې چې وار يې راوړے وى او اخوا ديخوا منډې وهى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_23.mp3', '', 1761754199, 1761754199),
(46788, 'Jeremiah 2:24', 'Jeremiah', 2, 24, 'تۀ لکه د هغه ځنګلى خرې په شان يې چې په دشته کښې په مستۍ راغلې وى او آوازونه شروع کړى نو څوک د هغې شهوت قابو کولے شى؟ او هر يو صحرائى خر به بغېر د تکليف نه په هغې باندې سورېدے شى او هغه په خپله هغوئ ته نزدې ورځى ځکه چې هغه په مستۍ کښې راغلې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_24.mp3', '', 1761754199, 1761754199),
(46789, 'Jeremiah 2:25', 'Jeremiah', 2, 25, 'نو بيا دومره منډې مۀ وهه چې څپلۍ دې وشليږى او مرۍ دې اوچه شى. نو بيا تا ووئيل، چې نه، دا خبرې زما دپاره بې‌فائدې دى، زۀ د غېرو د بُتانو سره مينه کوم، او زۀ به د هغوئ پيروى کوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_25.mp3', '', 1761754199, 1761754199),
(46790, 'Jeremiah 2:26', 'Jeremiah', 2, 26, '”اے بنى اِسرائيلو ستاسو ټول قوم او بادشاهان، مشران، اِمامان، او نبيان داسې شرمنده شئ لکه څنګه چې يو غل ونيولے شى او شرمنده وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_26.mp3', '', 1761754199, 1761754199),
(46791, 'Jeremiah 2:27', 'Jeremiah', 2, 27, 'دوئ د لرګى نه جوړ شوى بُت ته وائى چې تۀ زما پلار يې، او د کاڼى نه جوړ شوى بُت ته وائى چې تۀ زما مور يې. دوئ ټولو ما ته د مخ په ځائ شا کړې ده، خو چې کله هم څۀ تکليف ورباندې راشى نو بيا ما ته خواست کوى چې راشه او مونږ ته خلاصون راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_27.mp3', '', 1761754199, 1761754199),
(46792, 'Jeremiah 2:28', 'Jeremiah', 2, 28, 'نو بيا هغه معبودان چرته دى کوم چې تاسو د خپل ځان دپاره جوړ کړى دى؟ نو بيا کۀ دوئ کولے شى نو را دې شى او د مصيبت په وخت کښې دې تاسو له خلاصون درکړى. ځکه چې اے يهوداه، ستاسو خو دومره ډېر معبودان دى لکه څومره چې ستا ښارونه دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_28.mp3', '', 1761754199, 1761754199),
(46793, 'Jeremiah 2:29', 'Jeremiah', 2, 29, 'مالِک خُدائ فرمائى چې، ”نو بيا تاسو ولې په ما اِلزام لګوئ؟ تاسو ټولو زما خلاف سرکشى کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_29.mp3', '', 1761754199, 1761754199),
(46794, 'Jeremiah 2:30', 'Jeremiah', 2, 30, 'ما ستاسو خلقو ته بې‌فائدې سزا ورکړه، ځکه چې هغوئ زما اصلاح ‎کول ونۀ منل. خو تاسو لکه د غړمبېدونکى زمرى په شان په خپلو نبيانو حمله وکړه او هغوئ مو قتل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_30.mp3', '', 1761754199, 1761754199),
(46795, 'Jeremiah 2:31', 'Jeremiah', 2, 31, 'اے موجوده نسلونو، د مالِک خُدائ په کلام باندې غور او فکر وکړئ، ولې زۀ د بنى اِسرائيلو دپاره د صحرا او يا د تورې تيارې زمکې په شان وم څۀ؟ نو بيا ولې زما قوم داسې وائى چې اوس دوئ زما نه آزاد شُو، او بيا به هيڅکله ما ته واپس رانۀ شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_31.mp3', '', 1761754199, 1761754199),
(46796, 'Jeremiah 2:32', 'Jeremiah', 2, 32, 'ولې يوه پېغله خپل کالى هېروى، او يا يوه ناوې خپل د وادۀ سنګار او جامې هېروى څۀ؟ خو زما خلقو زۀ بې‌حده هېر کړے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_32.mp3', '', 1761754199, 1761754199),
(46797, 'Jeremiah 2:33', 'Jeremiah', 2, 33, 'د معشوقو په پېدا کولو کښې تاسو څومره ماهر يې. تر دې چې بدکاره ښځه به هم ستاسو نه چل زده کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_33.mp3', '', 1761754199, 1761754199),
(46798, 'Jeremiah 2:34', 'Jeremiah', 2, 34, 'ستاسو لمن د بې‌ګناه غريبانانو په وينو داغې شوې ده، سره د دې چې هغوئ تاسو په غلا کولو کښې نۀ دى نيولى. د دې هر څۀ باوجود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_34.mp3', '', 1761754199, 1761754199),
(46799, 'Jeremiah 2:35', 'Jeremiah', 2, 35, 'بيا هم تۀ وائې چې، ”ما هيڅ نۀ دى کړى زۀ بې‌ګناه يم، مالِک خُدائ خو ما ته غصه نۀ دے.“ خو زۀ به تا له سخته سزا درکړم ځکه چې تۀ وائې چې، ”زۀ بې‌ګناه يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_35.mp3', '', 1761754199, 1761754199),
(46800, 'Jeremiah 2:36', 'Jeremiah', 2, 36, 'تۀ کله دلته او کله هلته ځې راځې نو بيا ولې دومره زر خپلې لارې بدلوې؟ تۀ به د مِصر نه داسې وشرمېږې لکه څنګه چې تۀ وړاندې د اسور نه شرمېدلے وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_36.mp3', '', 1761754199, 1761754199),
(46801, 'Jeremiah 2:37', 'Jeremiah', 2, 37, 'تۀ به د هغه ځائ نه هم لاس په سر شرمنده وځې، ځکه چې په چا تا بهروسه کوله مالِک خُدائ هغوئ رد کړل نو تاسو به د هغوئ نه هيڅ امداد حاصل نۀ کړئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah2_verse_37.mp3', '', 1761754199, 1761754199),
(46802, 'Exodus 28:1', 'Exodus', 28, 1, 'خپل ورور هارون او د هغه زامن ناداب، ابیهو، العازار او ایتامار راوغواړه. هغوی د اسراییلو د خلکو څخه بېل کړه، ترڅو د کاهنانو په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_1.mp3', '', 1761754199, 1761754199),
(46803, 'Exodus 28:2', 'Exodus', 28, 2, 'خپل ورور هارون دپاره ځانګړي کالي جوړ کړه، ترڅو هغه ته عزت او ښکلا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_2.mp3', '', 1761754199, 1761754199),
(46804, 'Exodus 28:3', 'Exodus', 28, 3, 'ټولو هغو ماهرو خلکو ته چې ما ورته په داسې کارونو کې توان ورکړی دی ووایه چې د هارون دپاره کالي جوړ کړي، ترڅو هغه د کاهن په توګه زما خدمت ته وقف شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_3.mp3', '', 1761754199, 1761754199),
(46805, 'Exodus 28:4', 'Exodus', 28, 4, 'هغه کالي چې هغوی یې باید جوړ کړي دا دي: سینه پوښ، سپېڅلی پېشبند، چپنه، اوبدل شوی کمیس، لونګۍ او یوه پټۍ. هغوی دې دا ځانګړي کالي ستا ورور هارون او د هغه د زامنو دپاره جوړ کړي، ترڅو هغوی وکولای شي چې د کاهنانو په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_4.mp3', '', 1761754199, 1761754199),
(46806, 'Exodus 28:5', 'Exodus', 28, 5, 'هغه ماهر کس دې د ابي، بانجاني او سرو وړیو، د سرو زرو د تار او د ښه کتان څخه کار واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_5.mp3', '', 1761754199, 1761754199),
(46807, 'Exodus 28:6', 'Exodus', 28, 6, 'د سرو زرو تار او د ابي، بانجاني او سرو وړیو او د ښه کتان څخه سپېڅلی پېشبند جوړ کړه او په هغې کې دې ګلدوزي وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_6.mp3', '', 1761754199, 1761754199),
(46808, 'Exodus 28:7', 'Exodus', 28, 7, 'سپېڅلی پېشبند دې د اوږې دوه تسمې ولري چې د هغه په دواړو خواو باندې ونښلول شي چې پېشبند ورسره وتړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_7.mp3', '', 1761754199, 1761754199),
(46809, 'Exodus 28:8', 'Exodus', 28, 8, 'ښه اوبدل شوی کمربند چې د هماغه موادو څخه جوړ شي، هغه دې د سپېڅلي پېشبند سره ونښلول شي چې د یوې ټوټې په شان ښکاره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_8.mp3', '', 1761754199, 1761754199),
(46810, 'Exodus 28:9', 'Exodus', 28, 9, 'دوه د عقیقو تیږې واخله او د یعقوب د زامنو د نومونو نقش ورباندې وباسه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_9.mp3', '', 1761754199, 1761754199);